def resolve(path, cwd, links):
    max_links = 8
    links_followed = 0

    # Determine starting path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        # Check if it's a symlink
        if next_path in links:
            links_followed += 1
            if links_followed > max_links:
                return None

            target = links[next_path]

            # Determine starting point for target resolution
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if next_path == '/':
                    current = '/'
                else:
                    current = next_path.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace current components with target components + remaining
            remaining = components[i + 1:]
            components = target_components + remaining
            i = 0
        else:
            current = next_path
            i += 1

    # Return result with no trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

